"""Base strategy class."""

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from datetime import datetime
from typing import List, Dict, Optional
import logging

logger = logging.getLogger(__name__)


@dataclass
class Signal:
    """Trading signal generated by strategy."""
    
    timestamp: datetime
    symbol: str
    timeframe: str
    direction: str  # 'LONG' or 'SHORT'
    strategy_version: str
    rationale: str
    features: Dict[str, float] = field(default_factory=dict)
    
    def validate(self) -> List[str]:
        """Validate signal."""
        errors = []
        
        if self.direction not in ("LONG", "SHORT"):
            errors.append(f"Direction must be LONG or SHORT, got {self.direction}")
        
        if not self.strategy_version:
            errors.append("Strategy version required")
        
        if not self.rationale:
            errors.append("Rationale required")
        
        return errors


class BaseStrategy(ABC):
    """Abstract base for trading strategies."""

    def __init__(self, name: str, version: str, **params):
        """
        Initialize strategy.
        
        Args:
            name: Strategy name
            version: Strategy version
            **params: Strategy-specific parameters
        """
        self.name = name
        self.version = version
        self.params = params
        self._validate_params()

    def _validate_params(self) -> None:
        """Validate strategy parameters."""
        errors = self.validate_parameters(**self.params)
        if errors:
            raise ValueError(f"Invalid parameters: {'; '.join(errors)}")

    @abstractmethod
    def validate_parameters(self, **params) -> List[str]:
        """
        Validate strategy parameters.
        
        Args:
            **params: Parameters to validate
        
        Returns:
            List of validation errors
        """
        pass

    @abstractmethod
    def generate_signal(self, candles: List[dict]) -> Optional[Signal]:
        """
        Generate trading signal from completed candles.
        
        Must use only completed candles (not forming candle).
        
        Args:
            candles: List of candle dicts with OHLCV data
        
        Returns:
            Signal if conditions met, else None
        """
        pass

    def get_required_candles(self) -> int:
        """
        Return minimum candles needed for signal generation.
        
        Returns:
            Required candle count
        """
        return 50  # Default; override in subclasses
